import './App.css';

import React, { useState } from "react";
import { sendRequest } from "./requests/requests";

function App() {
  const [imageFile, setImageFile] = useState(null);
  const [secondImage, setSecondImage] = useState(null);
  const [operation, setOperation] = useState("gray");
  const [params, setParams] = useState({});
  const [resultUrl, setResultUrl] = useState("");

  const handleSubmit = async () => {
    if (!imageFile) {
      alert("Lütfen bir görsel seçin.");
      return;
    }

    const data = await sendRequest({
      operation,
      imageFile,
      secondImageFile: secondImage,
      params
    });
    setResultUrl(data.url);
  };

  const renderParams = () => {
    switch (operation) {
      case "binary":
        return (
          <input type="number" placeholder="Threshold"
            onChange={e => setParams({ threshold: Number(e.target.value) })} />
        );
      case "rotate":
        return (
          <input type="number" placeholder="Angle"
            onChange={e => setParams({ angle: Number(e.target.value) })} />
        );
      case "zoom":
        return (
          <input type="number" step="0.1" placeholder="Scale"
            onChange={e => setParams({ scale: Number(e.target.value) })} />
        );
      case "contrast":
        return (
          <input type="number" step="0.1" placeholder="Factor (0-1)"
            onChange={e => setParams({ factor: Number(e.target.value) })} />
        );
      case "motion":
      case "median":
        return (
          <input type="number" placeholder="Kernel Size"
            onChange={e => setParams({ kernel_size: Number(e.target.value) })} />
        );
      case "color":
        return (
          <input type="text" placeholder="Mode (HSV / YUV / Grayscale)"
            onChange={e => setParams({ mode: e.target.value })} />
        );
      case "double_threshold":
        return (
          <>
            <input type="number" placeholder="Low Threshold"
              onChange={e => setParams(prev => ({ ...prev, low_thresh: Number(e.target.value) }))} />
            <input type="number" placeholder="High Threshold"
              onChange={e => setParams(prev => ({ ...prev, high_thresh: Number(e.target.value) }))} />
          </>
        );
      case "edge":
        return (
          <>
            <input type="number" placeholder="Threshold 1"
              onChange={e => setParams(prev => ({ ...prev, threshold1: Number(e.target.value) }))} />
            <input type="number" placeholder="Threshold 2"
              onChange={e => setParams(prev => ({ ...prev, threshold2: Number(e.target.value) }))} />
          </>
        );
      case "crop":
        return (
          <>
            <input type="number" placeholder="X"
              onChange={e => setParams(prev => ({ ...prev, x: Number(e.target.value) }))} />
            <input type="number" placeholder="Y"
              onChange={e => setParams(prev => ({ ...prev, y: Number(e.target.value) }))} />
            <input type="number" placeholder="Width"
              onChange={e => setParams(prev => ({ ...prev, width: Number(e.target.value) }))} />
            <input type="number" placeholder="Height"
              onChange={e => setParams(prev => ({ ...prev, height: Number(e.target.value) }))} />
          </>
        );
      case "noise":
        return (
          <input type="number" step="0.01" placeholder="Amount (0-1)"
            onChange={e => setParams({ amount: Number(e.target.value) })} />
        );
      case "denoise":
        return (
          <>
            <select onChange={e => setParams(prev => ({ ...prev, filter_type: e.target.value }))}>
              <option value="">Filtre Türü Seçin</option>
              <option value="mean">Mean</option>
              <option value="median">Median</option>
            </select>
            <input type="number" placeholder="Kernel Size"
              onChange={e => setParams(prev => ({ ...prev, kernel_size: Number(e.target.value) }))} />
          </>
        );
      case "morphology":
        return (
          <>
            <select onChange={e => setParams(prev => ({ ...prev, morph_op: e.target.value }))}>
              <option value="">İşlem Seçin</option>
              <option value="dilate">Genişlet (Dilate)</option>
              <option value="erode">Aşındır (Erode)</option>
              <option value="open">Açma (Open)</option>
              <option value="close">Kapama (Close)</option>
            </select>
            <input type="number" placeholder="Kernel Size"
              onChange={e => setParams(prev => ({ ...prev, kernel_size: Number(e.target.value) }))} />
          </>
        );
      case "arithmetic":
        return (
          <>
            <input type="file" onChange={e => setSecondImage(e.target.files[0])} />
            <select onChange={e => setParams({ arithmetic_op: e.target.value })}>
              <option value="subtract">Çıkarma</option>
              <option value="multiply">Çarpma</option>
            </select>
          </>
        );
      default:
        return null;
    }
  };

  return (
    <div className="container">

      <h2>Görüntü İşleme Arayüzü</h2>

      <input type="file" accept="image/*" onChange={e => setImageFile(e.target.files[0])} />

      <select style={{ marginTop: "10px" }} onChange={e => {
        setOperation(e.target.value);
        setParams({});
        setSecondImage(null);
      }}>
        <option value="gray">Gri Dönüşüm</option>
        <option value="binary">Binary</option>
        <option value="rotate">Döndürme</option>
        <option value="crop">Kırpma</option>
        <option value="zoom">Yaklaştırma</option>
        <option value="color">Renk Uzayı</option>
        <option value="histogram">Histogram</option>
        <option value="contrast">Kontrast Azalt</option>
        <option value="median">Median</option>
        <option value="double_threshold">Çift Eşik</option>
        <option value="edge">Kenar Bul</option>
        <option value="noise">Gürültü Ekle</option>
        <option value="denoise">Gürültü Temizle</option>
        <option value="motion">Motion Blur</option>
        <option value="morphology">Morfoloji</option>
        <option value="arithmetic">Aritmetik İşlem</option>
      </select>

      <div style={{ marginTop: "10px" }}>
        {renderParams()}
      </div>

      <button style={{ marginTop: "15px" }} onClick={handleSubmit}>
        Uygula
      </button>

      {resultUrl && (
        <div style={{ marginTop: "20px" }}>
          <img src={resultUrl} alt="Sonuç" style={{ maxWidth: "100%", maxHeight: "400px" }} />
          <a href={resultUrl} download>
            <button style={{ marginTop: "10px" }}>İndir</button>
          </a>
        </div>
      )}
    </div>
  );
}

export default App;
